387	    @Transactional
388	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
389	            String corrects) {
390	        RollupService.Snapshot before = rollup.snapshot(sheetId);
391	        Person person = people.findByIdAndSheetId(personId, sheetId)
392	                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
393	        LocalDate dated = dateOr(sheetId, date);
394	        periods.requireOpen(sheetId, dated);
395	        person.requireClaimable(dated);
396	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
397	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
398	        claim.setCorrects(corrects);
399	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
400	        // Due by its date plus the terms of its person's grade on that date, fixed from now on.
401	        claim.setDueBy(dated.plusDays(settings.termsFor(sheetId, person.gradeOn(dated), dated)));
402	        claim.setListed(sheets.nextListed(sheetId));
403	        Claim saved = claims.saveAndFlush(claim);
404	        log(sheetId, user, person, saved);
405	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
406	        rollup.recordChanges(sheetId, user, before);
407	        return saved;
408	    }
