410	    @Transactional
411	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
412	            String corrects) {
413	        RollupService.Snapshot before = rollup.snapshot(sheetId);
414	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
415	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
416	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
417	        if (claim.getStatus() != ClaimStatus.DRAFT) {
418	            throw new ClaimNotEditableException(id, claim.getStatus());
419	        }
420	        LocalDate dated = dateOr(sheetId, date);
421	        // Neither out of nor into a closed period.
422	        periods.requireOpen(sheetId, claim.getDate(), dated);
423	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
424	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
425	                .requireClaimable(dated);
426	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
427	        claim.setAmount(amount);
428	        claim.setCorrects(corrects);
429	        claim.setDate(dated);
430	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
431	        claim.setNote(noteOf(note));
432	        Claim saved = claims.saveAndFlush(claim);
433	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
434	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
435	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
436	        rollup.recordChanges(sheetId, user, before);
437	        return saved;
438	    }
