440	    /**
441	     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
442	     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
443	     */
444	    @Transactional
445	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
446	        Claim claim = claims.findForUpdate(id, sheetId)
447	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
448	        if (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING) {
449	            throw new ClaimStatusException(id, claim.getStatus(), status);
450	        }
451	        periods.requireOpen(sheetId, claim.getDate());
452	        // Four eyes: whoever opened a claim cannot also settle it.
453	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
454	            throw new ClaimSettledByOpenerException(id, user);
455	        }
456	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
457	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
458	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
459	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
460	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
461	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
462	            BigDecimal due = withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
463	            if (limit != null && due != null && due.compareTo(limit) > 0) {
464	                status = ClaimStatus.PENDING;
465	            }
466	        }
467	        RollupService.Snapshot before = rollup.snapshot(sheetId);
468	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim) : "";
469	        claim.setStatus(status);
470	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
471	        String number = claim.getNumber();
472	        if (status == ClaimStatus.OPEN) {
473	            number = nextNumber(sheetId, claim.getDate());
474	            claim.setNumber(number);
475	            claim.setOpenedBy(user);
476	        }
477	        Claim saved = claims.saveAndFlush(claim);
478	        log(sheetId, user, person, saved);
479	        String event = switch (status) {
480	            case OPEN -> "CLAIM_OPENED";
481	            case PENDING -> "CLAIM_PENDING";
482	            case SETTLED -> "CLAIM_SETTLED";
483	            case VOID -> "CLAIM_VOIDED";
484	            case DRAFT -> throw new IllegalStateException();
485	        };
486	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
487	        rollup.recordChanges(sheetId, user, before);
488	        return saved;
489	    }
