491	    /**
492	     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
493	     * its live figure.
494	     */
495	    @Transactional
496	    public Claim approve(String sheetId, String user, Long id) {
497	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
498	        if (user.equals(claim.getOpenedBy())) {
499	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
500	        }
501	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
502	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
503	        RollupService.Snapshot before = rollup.snapshot(sheetId);
504	        String due = settle(sheetId, person, claim);
505	        claim.setStatus(ClaimStatus.SETTLED);
506	        Claim saved = claims.saveAndFlush(claim);
507	        log(sheetId, user, person, saved);
508	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
509	        rollup.recordChanges(sheetId, user, before);
510	        return saved;
511	    }
