513	    /**
514	     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
515	     * if that statement included it.
516	     */
517	    @Transactional
518	    public Claim reject(String sheetId, String user, Long id, String reason) {
519	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
520	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
521	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
522	        RollupService.Snapshot before = rollup.snapshot(sheetId);
523	        claim.setStatus(ClaimStatus.OPEN);
524	        Claim saved = claims.saveAndFlush(claim);
525	        log(sheetId, user, person, saved);
526	        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
527	                + " reason=" + reason);
528	        rollup.recordChanges(sheetId, user, before);
529	        return saved;
530	    }
