532	    /**
533	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
534	     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
535	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
536	     * retired before its date, or a user not a steward.
537	     */
538	    @Transactional
539	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
540	        Claim claim = claims.findForUpdate(id, sheetId)
541	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
542	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
543	            throw new ClaimReassignForbiddenException(id, user);
544	        }
545	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
546	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
547	        }
548	        if (claim.getPersonId().equals(toPersonId)) {
549	            throw new ClaimReassignException(id, "it is already that person's");
550	        }
551	        periods.requireOpen(sheetId, claim.getDate());
552	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
553	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
554	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
555	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
556	        to.requireClaimable(claim.getDate());
557	        RollupService.Snapshot before = rollup.snapshot(sheetId);
558	        claim.setPersonId(to.getId());
559	        claim.setStated(false, null);
560	        claim.setListed(sheets.nextListed(sheetId));
561	        Claim saved = claims.saveAndFlush(claim);
562	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
563	                + " from=" + from.getName() + " to=" + to.getName());
564	        rollup.recordChanges(sheetId, user, before);
565	        return saved;
566	    }
