568	    /**
569	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
570	     * bound by no statement (today's rates, grades and floor, with its late charge as of today). Refused for any other
571	     * status, a closed period, or a user not a steward.
572	     */
573	    @Transactional
574	    public Claim resettle(String sheetId, String user, Long id) {
575	        Claim claim = claims.findForUpdate(id, sheetId)
576	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
577	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
578	            throw new ClaimResettleForbiddenException(id, user);
579	        }
580	        if (claim.getStatus() != ClaimStatus.SETTLED) {
581	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
582	        }
583	        periods.requireOpen(sheetId, claim.getDate());
584	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
585	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
586	        RollupService.Snapshot before = rollup.snapshot(sheetId);
587	        String old = shownDue(sheetId, person, claim);
588	        BigDecimal figure = dueOf(sheetId, person, claim);
589	        claim.setSettledDue(settings.get(sheetId).withLateCharge(figure, !claim.isCorrection(), claim.getDueBy(),
590	                claim.getDate()));
591	        Claim saved = claims.saveAndFlush(claim);
592	        log(sheetId, user, person, saved);
593	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
594	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
595	        rollup.recordChanges(sheetId, user, before);
596	        return saved;
597	    }
