599	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
600	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
601	        Claim claim = claims.findForUpdate(id, sheetId)
602	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
603	        if (claim.getStatus() != ClaimStatus.PENDING) {
604	            throw new ClaimStatusException(id, claim.getStatus(), to);
605	        }
606	        periods.requireOpen(sheetId, claim.getDate());
607	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
608	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
609	        }
610	        return claim;
611	    }
