613	    /**
614	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
615	     * the rate on the claim's date) with its late charge frozen in; with no figure it stays live. Gives the due at the
616	     * end of its audit record.
617	     */
618	    private String settle(String sheetId, Person person, Claim claim) {
619	        BigDecimal figure = figureOf(sheetId, person, claim);
620	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
621	                : figure.add(settings.get(sheetId).lateCharge(figure, claim.getDueBy(), claim.getDate()));
622	        claim.setSettledDue(settledDue);
623	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
624	    }
