626	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
627	    private void log(String sheetId, String user, Person person, Claim claim) {
628	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
629	                shownDue(sheetId, person, claim)));
630	    }
631	
632	    /**
633	     * The claim's due as shown: the one fixed when it was settled, else its figure with its late charge on top; two
634	     * decimals, or n/a.
635	     */
636	    private String shownDue(String sheetId, Person person, Claim claim) {
637	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
638	                : withLateCharge(sheetId, claim, figureOf(sheetId, person, claim));
639	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
640	    }
