642	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
643	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
644	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
645	    }
