647	    /**
648	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
649	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
650	     * for any other claim.
651	     */
652	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
653	        if (amount.signum() >= 0) {
654	            if (corrects != null) {
655	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
656	            }
657	            return null;
658	        }
659	        if (corrects == null) {
660	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
661	        }
662	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
663	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
664	                .map(Claim::getDate)
665	                .orElseThrow(() -> new ClaimCorrectionException(
666	                        "Claim " + corrects + " is not a settled claim of the same person"));
667	    }
668	
669	    /**
670	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
671	     * date has the claim round, raised to the sheet's floor on its date unless it is a correction; null (n/a) with no rate.
672	     */
673	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
674	        Sheet sheet = settings.get(sheetId);
675	        BigDecimal due = rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
676	                .map(Rate::getPct)
677	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
678	                .orElse(null);
679	        return claim.isCorrection() ? due : sheet.floored(due, claim.getDate());
680	    }
681	
682	    /**
683	     * The due with the late charge of an OPEN or PENDING claim overdue on the sheet's today added on top (none on a
684	     * correction); null (n/a) stays null.
685	     */
686	    private BigDecimal withLateCharge(String sheetId, Claim claim, BigDecimal due) {
687	        return settings.get(sheetId).withLateCharge(due,
688	                claim.getStatus().isOpen() && !claim.isCorrection(), claim.getDueBy(), claim.getDate());
689	    }
690	
691	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
692	    private static String record(String event, String user, Person person, Claim claim) {
693	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
694	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
695	                + " date=" + claim.getDate();
696	    }
697	
698	    /** The claim's number at the end of an audit record, or nothing when it has none. */
699	    private static String numberOf(String number) {
700	        return number == null ? "" : " number=" + number;
701	    }
702	
703	    /**
704	     * The number a claim dated on the date gets when opened: while the sheet numbers by period, the next in its
705	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
706	     */
707	    private String nextNumber(String sheetId, LocalDate date) {
708	        if (settings.get(sheetId).numbersByPeriod()) {
709	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
710	        }
711	        return String.valueOf(sheets.nextClaimNumber(sheetId));
712	    }
713	
714	    private LocalDate dateOr(String sheetId, LocalDate date) {
715	        return date != null ? date : sheets.today(sheetId);
716	    }
717	
718	    private static String noteOf(String note) {
719	        return note == null ? "" : note.trim();
720	    }
721	}
